# ── 批注搬家 ──────────────────────────────────────────────────────────────
def _move_anchors(conn: sqlite3.Connection, paper_id: int,
                  moves: dict[str, list[RefSpan]], by_id: dict[str, Block],
                  *, log: Callable[..., None] = print) -> tuple[int, int]:
    """把钉在**被合并掉的碎片**上的笔记/划痕搬到新条目上。

    坐标语义（㉛）：`(block_id, lang, start, end)`，`start/end` 是**裸文本**字符偏移。
    - `lang == "en"` → 直接过 `RefSpan` 的空白归一化映射（精确）；
    - `lang == "zh"` → 免中文碎片的中文栏是**原文回落**，所以先在英文坐标系里定位，
      再按"标题那一段换成了中文"的长度差平移（`_to_zh`）。没译出来的条目坐标不变。
    - 整块锚（`start IS NULL`）→ 只换块 id，落到覆盖碎片开头的那一条上。
    """
    moved = dropped = 0
    for table in ("notes", "highlights"):
        rows = conn.execute(
            f"SELECT id, block_id, lang, start, end FROM {table} WHERE paper_id=?",
            (paper_id,)).fetchall()
        for r in rows:
            spans = moves.get(r["block_id"])
            if not spans:
                continue
            if r["start"] is None or r["end"] is None:
                who = _span_for(spans, 0)
                if who is None:
                    dropped += 1
                    continue
                conn.execute(f"UPDATE {table} SET block_id=? WHERE id=?",
                             (who.new_id, r["id"]))
                moved += 1
                continue
            who = _span_for(spans, r["start"])
            if who is None:
                dropped += 1
                log(f"    ⚠️ {table}#{r['id']} 的锚点落在碎片之外（块 {r['block_id']} 已合并）→ 未搬家")
                continue
            s, e = who.move(int(r["start"]), int(r["end"]))
            if r["lang"] == "zh":
                s, e = _to_zh(by_id.get(who.new_id), s, e)
            conn.execute(f"UPDATE {table} SET block_id=?, start=?, end=? WHERE id=?",
                         (who.new_id, s, e, r["id"]))
            moved += 1
            log(f"    · {table}#{r['id']}：{r['block_id']} {r['lang']} {r['start']}–{r['end']}"
                f" → {who.new_id} {s}–{e}")
    return moved, dropped


def _span_for(spans: list[RefSpan], offset: int) -> RefSpan | None:
    """碎片内偏移 `offset` 落在哪个新块里（都不命中就退到最靠后那个起点）。"""
    best: RefSpan | None = None
    for sp in spans:
        if sp.start <= sp.base + offset < sp.end:
            return sp
        if sp.base <= sp.base + offset and (best is None or sp.start > best.start):
            best = sp
    return best if best is not None else (spans[0] if spans else None)


def _to_zh(b: Block | None, s: int, e: int) -> tuple[int, int]:
    """英文坐标系区间 → 中文栏坐标系（标题换成中文后长度变了）。

    `ref` 块的中文 = 原条目里**把标题那一段换成中文**（`ref_zh_text`），所以映射恰好是
    一条"分段平移"：标题之前不动、标题之后平移 `len(title_zh) - len(title_en)`，
    落进标题里的字符夹到标题开头。没译出来（中文栏回落原文）时坐标原样返回。
    """
    if b is None or not (b.zh or "").strip():
        return s, e
    pay = b.payload or {}
    t_en, t_zh = pay.get("title_en") or "", pay.get("title_zh") or ""
    span = title_span(b.en, t_en) if t_en else None
    if span is None:
        return s, e
    a, z = span
    tail = b.en[z - 1] if 0 < z <= len(b.en) and b.en[z - 1] in ".。" else ""
    delta = len(t_zh) + len(tail) - (z - a)

    def f(p: int) -> int:
        if p <= a:
            return p
        if p >= z:
            return min(p + delta, len(b.zh))
        return a

    ns, ne = f(s), f(e)
    return ns, max(ne, ns)

    log.info("  ⤴ %s 类型修订：%s → %s（%s）", b.id, old, want, a.get("reason") or "")
    return ToolOut(f"{b.id}：{old} → {want}（文字未动）。")

def _t_split_block(self, a: dict) -> ToolOut:
    b = self._find(str(a.get("id") or ""))
    if b is None:
        return ToolOut(f"没有块 {a.get('id')}", error=True)
    parts = [clean_text(p).strip() for p in (a.get("parts") or []) if isinstance(p, str) and p.strip()]
    if len(parts) < 2:
        self.stats.rejected += 1
        return ToolOut("切分被拒绝：parts 至少两段非空文本。", error=True)
    ok, why = _acceptable_text_change(b.en, "\n\n".join(parts))
    if not ok:
        self.stats.rejected += 1
        return ToolOut(f"切分被护栏拒绝：{why}", error=True)
    pos = self.doc.blocks.index(b)
    b.en = parts[0]
    fresh = []
    for text in parts[1:]:
        # 逐个把"已分配的"传进去，否则多个新块会共用一个 ID（见 `_next_id` 说明）
        nb = Block(id=_next_id(self.doc, {n.id for n in fresh}), type=b.type, en=text,
                   section=b.section, level=b.level, payload=dict(b.payload))
        fresh.append(nb)
    for i, nb in enumerate(fresh):
        self.doc.blocks.insert(pos + 1 + i, nb)
    self.stats.split += 1
    log.info("  ⇤ %s 拆成 %d 块（%s）", b.id, len(parts), a.get("reason") or "")
    return ToolOut(f"{b.id} 已拆成 {len(parts)} 块，新块号：{[n.id for n in fresh]}。")

def _t_merge_block(self, a: dict) -> ToolOut:
    b = self._find(str(a.get("id") or ""))
    if b is None:
        return ToolOut(f"没有块 {a.get('id')}", error=True)
    page_bs = self._page_blocks(int(b.payload.get("page") or 0))
    pos = page_bs.index(b) if b in page_bs else -1
    prev = page_bs[pos - 1] if pos > 0 else None
    if prev is None or prev.type == "figure":
        self.stats.rejected += 1
        return ToolOut("合并被拒绝：这一页里没有可并入的前一块（它是本页第一块）。", error=True)
    tail_prev, head_b = prev.en.rstrip(), b.en.lstrip()   # 合并前留证据（合并后就分不出来了）
    prev.en = clean_text((tail_prev + " " + head_b).strip())
    self.doc.blocks.remove(b)
    self.stats.merged += 1
    log.info("  ⇥ %s 并入 %s（%s）", b.id, prev.id, a.get("reason") or "")
    # ⚠️ **软提醒，不是拒绝**：合并是**不可逆的语义决定**，而"这到底是不是同一句话"
    # 只有看图的人（agent）知道。这里只用**和标记同一套判据**复量一遍：
    # 前块已收句 + 本块大写起 ⇒ 不太像同一句 —— 那时把话说清（怎么拆回来），
    # 而不是硬拦（硬拦会让 agent 在真正需要合并时无路可走：没有别的工具能连两块）。
    out = f"{b.id} 已并入 {prev.id}。"
    if not _looks_like_continuation(tail_prev, head_b):
        out += (" ⚠️ 程序复量后**不太像**同一句（前一块读作已收句、或本块以大写起）。"
                "你若是有意合并就忽略这条；若是并错了，用 `split_block` 拆回两段。")
    return ToolOut(out)

